/**
 * Full preset picker, pushed from Settings' compact Theme row. Two labeled sections -- Light and
 * Dark, 5 presets each -- rather than the old single combined light/dark grid (`ThemePickerGrid`,
 * now deleted). Section ORDER follows the device's own OS light/dark setting (`isSystemInDarkTheme()`),
 * not the app's currently-selected preset -- a device in system dark mode sees Dark first, a device
 * in system light mode sees Light first. This is a narrow, deliberate use of `isSystemInDarkTheme()`
 * purely to order these two sections; it does NOT drive which preset is actually applied (the app's
 * own selected preset overrides OS dark mode everywhere else, per `Theme.kt`'s own doc comment).
 *
 * Stateless, no `Scaffold`/`TopAppBar` -- same bare-back-button chrome every other screen reached
 * from Settings now uses (see `DocumentSectionsScreen`'s doc comment).
 */
@Composable
fun ThemePickerScreen(
    presets: List<MarketPulseTheme>,
    selectedTheme: MarketPulseTheme,
    onPresetSelected: (MarketPulseTheme) -> Unit,
    onNavigateUp: () -> Unit
) {
    val systemInDark = isSystemInDarkTheme()
    val lightPresets = presets.filter { !it.isDark }
    val darkPresets = presets.filter { it.isDark }

    Column(
        modifier = Modifier
            .fillMaxSize()
            .windowInsetsPadding(WindowInsets.statusBars)
            .verticalScroll(rememberScrollState())
    ) {
        IconButton(onClick = onNavigateUp) {
            Icon(
                painter = painterResource(id = R.drawable.ic_back),
                contentDescription = stringResource(id = R.string.nav_back_content_description),
                tint = LocalPulseColors.current.onSurfaceMuted
            )
        }
        Column(modifier = Modifier.padding(dimensionResource(id = R.dimen.padding_large))) {
            Text(
                text = stringResource(id = R.string.settings_section_theme),
                style = MaterialTheme.typography.headlineSmall.copy(fontWeight = FontWeight.Bold),
                color = MaterialTheme.colorScheme.onBackground
            )
            Spacer(modifier = Modifier.height(dimensionResource(id = R.dimen.padding_xlarge)))

            val sections = if (systemInDark) {
                listOf(
                    R.string.settings_preset_mode_dark to darkPresets,
                    R.string.settings_preset_mode_light to lightPresets
                )
            } else {
                listOf(
                    R.string.settings_preset_mode_light to lightPresets,
                    R.string.settings_preset_mode_dark to darkPresets
                )
            }

            sections.forEachIndexed { index, (labelRes, presets) ->
                ThemePickerSectionHeader(text = stringResource(id = labelRes))
                Spacer(modifier = Modifier.height(dimensionResource(id = R.dimen.padding_medium)))
                PresetSwatchGrid(
                    presets = presets,
                    selectedTheme = selectedTheme,
                    onPresetSelected = onPresetSelected,
                    modifier = Modifier.fillMaxWidth()
                )
                if (index != sections.lastIndex) {
                    Spacer(modifier = Modifier.height(dimensionResource(id = R.dimen.padding_xxlarge)))
                }
            }
        }
    }
}

@Composable
private fun ThemePickerSectionHeader(text: String) {
    Text(
        text = text,
        style = MaterialTheme.typography.titleMedium.copy(fontWeight = FontWeight.Bold),
        color = LocalPulseColors.current.accentPrimary
    )
}

